// ─── DEMO MODE: Return fixture route data ─────────────────────────────────
// Used when demo_mode=true or when real routing fails.
// Clearly labelled as demo data in all outputs.
const d = $input.first().json;
const tripId = d.trip_id;

return [{json: {
  trip_id: tripId,
  routes: [
    {
      route_id: tripId + '-R1',
      label: 'Recommended – Lower reported-risk exposure',
      duration_seconds: 1320,
      distance_meters: 3100,
      risk_level: 'MEDIUM',
      risk_score: 0.38,
      risk_summary: '[DEMO DATA] 3 incidents reported within 500m over last 90 days. Moderate street lighting after 21:00.',
      incident_count: 3,
      geometry: [
        [d.origin_lng, d.origin_lat],
        [d.origin_lng + 0.004, d.origin_lat + 0.002],
        [d.dest_lng, d.dest_lat]
      ],
      is_demo_data: true
    },
    {
      route_id: tripId + '-R2',
      label: 'Shorter route – Higher reported-risk exposure (+3 min)',
      duration_seconds: 1020,
      distance_meters: 2200,
      risk_level: 'HIGH',
      risk_score: 0.72,
      risk_summary: '[DEMO DATA] 7 incidents within 300m. Isolated stretch with poor lighting. 2 harassment reports at night.',
      incident_count: 7,
      geometry: [
        [d.origin_lng, d.origin_lat],
        [d.origin_lng + 0.007, d.origin_lat - 0.001],
        [d.dest_lng, d.dest_lat]
      ],
      is_demo_data: true
    }
  ]
}}];

// ─── RISK ENGINE ──────────────────────────────────────────────────────────────
// Deterministic geographic risk scoring. No LLM involvement in the score itself.
// Inputs: ORS route geometry + Pinecone crime records
// ─────────────────────────────────────────────────────────────────────────────

const SEVERITY = {
  violent_crime: 1.0, sexual_assault: 1.0, robbery: 0.85,
  kidnapping: 0.95, assault: 0.75, harassment: 0.55,
  theft: 0.40, vandalism: 0.25, traffic_incident: 0.20,
  other: 0.30
};
const LOW_THRESH = 0.3, MED_THRESH = 0.6, CORRIDOR_KM = 0.5, MAX_WEIGHT = 10;
const HALF_LIFE_DAYS = 60, SIGMA_KM = 0.3;

function haversine(lat1, lng1, lat2, lng2) {
  const R = 6371, dLat=(lat2-lat1)*Math.PI/180, dLng=(lng2-lng1)*Math.PI/180;
  const a = Math.sin(dLat/2)**2 + Math.cos(lat1*Math.PI/180)*Math.cos(lat2*Math.PI/180)*Math.sin(dLng/2)**2;
  return R*2*Math.atan2(Math.sqrt(a), Math.sqrt(1-a));
}
function recency(d)  { return Math.pow(0.5, d / HALF_LIFE_DAYS); }
function distDecay(d){ return Math.exp(-(d*d)/(2*SIGMA_KM*SIGMA_KM)); }
function level(s)    { return s < LOW_THRESH ? 'LOW' : s < MED_THRESH ? 'MEDIUM' : 'HIGH'; }

// Parse crime incidents from Pinecone results
// Expected Pinecone metadata: {lat, lng, category, incident_date, description}
const pineconeResults = $('Pinecone: Crime Data Lookup').all?.() ?? [];
const incidents = pineconeResults.map(item => {
  const meta = item.json?.metadata ?? {};
  const incDate = meta.incident_date ? new Date(meta.incident_date) : null;
  const daysOld = incDate ? Math.floor((Date.now()-incDate.getTime())/(1000*60*60*24)) : 180;
  return {
    lat: parseFloat(meta.lat ?? meta.latitude ?? 0),
    lng: parseFloat(meta.lng ?? meta.longitude ?? 0),
    category: (meta.category ?? meta.crime_type ?? 'other').toLowerCase().replace(/[^a-z_]/g,'_'),
    days_old: daysOld,
    description: meta.description ?? ''
  };
}).filter(i => i.lat && i.lng);

// Parse ORS routes
const orsBody = $input.first().json;
const orsRoutes = orsBody.routes ?? [];

const scoredRoutes = orsRoutes.map((route, idx) => {
  const coords = route.geometry?.coordinates ?? route.geometry ?? [];
  let total = 0; const evidence = [];

  for (const inc of incidents) {
    let minDist = Infinity;
    for (const pt of coords) {
      const d = haversine(inc.lat, inc.lng, pt[1], pt[0]);
      if (d < minDist) minDist = d;
    }
    if (minDist > CORRIDOR_KM) continue;
    const sev = SEVERITY[inc.category] ?? 0.35;
    const w = sev * recency(inc.days_old) * distDecay(minDist);
    total += w;
    evidence.push({ category: inc.category, days_old: inc.days_old, distance_km: minDist.toFixed(3) });
  }

  const score = Math.min(total / MAX_WEIGHT, 1.0);
  const riskLevel = level(score);
  const durationSec = route.summary?.duration ?? (idx === 0 ? 1200 : 900);
  const distanceM   = route.summary?.distance ?? (idx === 0 ? 3000 : 2000);

  return {
    route_id: $('Validate & Parse Input').first().json.trip_id + '-R' + (idx+1),
    label: idx === 0 ? 'Recommended – Lower reported-risk' : `Route ${idx+1} – ${riskLevel === 'HIGH' ? 'Higher' : 'Moderate'} reported-risk`,
    duration_seconds: Math.round(durationSec),
    distance_meters: Math.round(distanceM),
    risk_level: riskLevel,
    risk_score: parseFloat(score.toFixed(4)),
    risk_summary: evidence.length > 0
      ? `${evidence.length} incidents found near this route (${evidence.slice(0,3).map(e=>e.category).join(', ')}${evidence.length>3?', ...':''}).`
      : 'No reported incidents found near this route in the dataset.',
    incident_count: evidence.length,
    geometry: coords,
    is_demo_data: false,
    _evidence: evidence.slice(0, 5)
  };
});

// Sort by risk_score ascending (safest first)
scoredRoutes.sort((a, b) => a.risk_score - b.risk_score);

return [{json: {
  trip_id: $('Validate & Parse Input').first().json.trip_id,
  routes: scoredRoutes,
  incident_data_count: incidents.length,
  is_demo_data: false
}}];
